    put('android/os/Handler.java','''package android.os;import java.util.*;public class Handler {final Looper loop;public static boolean reject;static class Task{Looper loop;Runnable run;Task(Looper l,Runnable r){loop=l;run=r;}}static final List<Task> pending=new ArrayList<>();public Handler(Looper l){loop=l;}public boolean post(Runnable r){if(reject||loop.quit)return false;pending.add(new Task(loop,r));return true;}public static void drain(boolean main){int n=0;while(true){Task next=null;for(Task t:pending)if(t.loop.ui==main){next=t;break;}if(next==null)return;if(++n>1000)throw new IllegalStateException("HOST_LOOP_LIMIT");pending.remove(next);Looper before=Looper.running;Looper.running=next.loop;try{next.run.run();}finally{Looper.running=before;}}}}''')
